package com.pranit.productsupport.core.service;
import com.pranit.productsupport.contracts.TicketStatus; import java.util.EnumSet; import java.util.Map; import java.util.Set;
public final class TicketStatusPolicy {private TicketStatusPolicy(){} private static final Map<TicketStatus,Set<TicketStatus>> NEXT=Map.of(TicketStatus.OPEN,EnumSet.of(TicketStatus.IN_REVIEW,TicketStatus.REJECTED),TicketStatus.IN_REVIEW,EnumSet.of(TicketStatus.WAITING_FOR_CUSTOMER,TicketStatus.RESOLVED,TicketStatus.REJECTED),TicketStatus.WAITING_FOR_CUSTOMER,EnumSet.of(TicketStatus.IN_REVIEW),TicketStatus.RESOLVED,EnumSet.of(TicketStatus.CLOSED,TicketStatus.IN_REVIEW),TicketStatus.CLOSED,EnumSet.noneOf(TicketStatus.class),TicketStatus.REJECTED,EnumSet.noneOf(TicketStatus.class)); public static boolean canTransition(TicketStatus from,TicketStatus to){return NEXT.getOrDefault(from,Set.of()).contains(to);} }
